{
  "decisions": [
    {
      "requirement_id": "ETC-101",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies a behavioral response (immediate fulfillment) to a specific input condition (absence of start sub-conditions) which must be observed by executing the system with crafted trackside messages."
    },
    {
      "requirement_id": "ETC-102",
      "methods": [
        "Test"
      ],
      "rationale": "The OBU's handling of driver acknowledgement as either a sole or additional end condition is a dynamic behavior that requires simulating driver inputs and observing the display state to verify."
    },
    {
      "requirement_id": "ETC-103",
      "methods": [
        "Test"
      ],
      "rationale": "Verifying that the message is not displayed when the end condition is already met at the start moment requires a runtime test where the timing of start and end conditions is controlled and the display output is monitored."
    },
    {
      "requirement_id": "ETC-104",
      "methods": [
        "Test"
      ],
      "rationale": "The calculation of the display length based on the start location is a functional behavior that can be verified by moving the OBU through a defined track section and measuring the distance over which the text remains visible."
    },
    {
      "requirement_id": "ETC-105",
      "methods": [
        "Test"
      ],
      "rationale": "The transmission of a specific report to the RBC upon driver acknowledgement is a system interaction that must be verified by capturing and analyzing the communication traffic during a test run."
    },
    {
      "requirement_id": "ETC-106",
      "methods": [
        "Test"
      ],
      "rationale": "The rejection of a duplicate message identifier while a previous one is pending is a state-dependent behavior that requires a sequence of inputs (receive, hold, receive duplicate) and observation of the rejection response."
    },
    {
      "requirement_id": "ETC-107",
      "methods": [
        "Test"
      ],
      "rationale": "The specific logic for deleting or keeping Mode Profiles based on the infill reference location is a complex state transition that must be verified by simulating infill scenarios and inspecting the resulting internal state or behavior."
    },
    {
      "requirement_id": "ETC-108",
      "methods": [
        "Test"
      ],
      "rationale": "The treatment of the Mode Profile start as a temporary EOA and the calculation of the temporary SvL are dynamic safety behaviors that require runtime simulation of the OBU's movement and speed monitoring to verify."
    },
    {
      "requirement_id": "ETC-109",
      "methods": [
        "Test"
      ],
      "rationale": "The replacement of stored LX information upon receiving a new message with the same identity is a data management behavior that can be verified by sending sequential LX messages and checking the stored data or subsequent behavior."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-051",
      "methods": [
        "Test"
      ],
      "rationale": "HttpOnly attribute presence and Set-Cookie header usage are verified by inspecting HTTP response headers during a live session."
    },
    {
      "requirement_id": "KDH-052",
      "methods": [
        "Test"
      ],
      "rationale": "The presence and values of the Strict-Transport-Security header are verified by inspecting HTTP response headers."
    },
    {
      "requirement_id": "KDH-053",
      "methods": [
        "Test"
      ],
      "rationale": "File upload validation is verified by submitting files with mismatched extensions and contents to observe rejection behavior."
    },
    {
      "requirement_id": "KDH-054",
      "methods": [
        "Test"
      ],
      "rationale": "Image size validation is verified by uploading images exceeding the defined pixel limits to observe rejection."
    },
    {
      "requirement_id": "KDH-055",
      "methods": [
        "Test"
      ],
      "rationale": "User enumeration prevention is verified by comparing error messages, HTTP codes, and response times for valid and invalid credentials."
    },
    {
      "requirement_id": "KDH-056",
      "methods": [
        "Test"
      ],
      "rationale": "Help Desk permissions are verified by attempting to initiate resets and change passwords to confirm only initiation is allowed."
    },
    {
      "requirement_id": "KDH-057",
      "methods": [
        "Test"
      ],
      "rationale": "Session token rotation is verified by authenticating and checking that a new token is issued and the old one is invalidated."
    },
    {
      "requirement_id": "KDH-058",
      "methods": [
        "Test"
      ],
      "rationale": "Session invalidation is verified by attempting to use a session token after logout or expiration to confirm access is denied."
    },
    {
      "requirement_id": "KDH-059",
      "methods": [
        "Test"
      ],
      "rationale": "Reauthentication requirement is verified by attempting sensitive changes after the 5-minute window to confirm the block and subsequent success after reauth."
    },
    {
      "requirement_id": "KDH-060",
      "methods": [
        "Test"
      ],
      "rationale": "Access control is verified by attempting to access other users' data using modified identifiers to confirm denial of unauthorized access."
    },
    {
      "requirement_id": "KDH-061",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Text alternatives and ARIA labels are verified by inspecting the HTML source code for appropriate attributes."
    },
    {
      "requirement_id": "KDH-062",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Semantic structure is verified by inspecting the HTML source for correct use of headings, tables, and lists."
    },
    {
      "requirement_id": "KDH-063",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Orientation independence is verified by rotating the device or resizing the window to observe that content remains usable."
    },
    {
      "requirement_id": "KDH-064",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Form field purposes are verified by inspecting the HTML source for autocomplete attributes."
    },
    {
      "requirement_id": "KDH-065",
      "methods": [
        "Analiz"
      ],
      "rationale": "Contrast ratios are verified by calculating the luminance difference between text and background colors."
    },
    {
      "requirement_id": "KDH-066",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Text resizing is verified by zooming the browser to 200% and observing that content remains readable and functional."
    },
    {
      "requirement_id": "KDH-067",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Use of text instead of images is verified by inspecting the HTML source to ensure information is not locked in images."
    },
    {
      "requirement_id": "KDH-068",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Spacing adjustments are verified by applying CSS overrides to increase line and paragraph spacing and observing layout integrity."
    },
    {
      "requirement_id": "KDH-069",
      "methods": [
        "Test"
      ],
      "rationale": "Keyboard accessibility is verified by navigating and interacting with all functions using only the keyboard."
    },
    {
      "requirement_id": "KDH-070",
      "methods": [
        "Test"
      ],
      "rationale": "Session timeout warning is verified by waiting 25 minutes of inactivity to observe the dialog, screen reader announcement, and extension functionality."
    },
    {
      "requirement_id": "KDH-071",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Page titles are verified by inspecting the HTML source for the presence of a <title> element on each page."
    },
    {
      "requirement_id": "KDH-072",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Link purpose clarity is verified by inspecting the HTML source to ensure link text or aria-labels provide sufficient context."
    },
    {
      "requirement_id": "KDH-073",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Focus visibility is verified by navigating with the keyboard and observing that a visible focus indicator appears on each element."
    },
    {
      "requirement_id": "KDH-074",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Page language is verified by inspecting the HTML source for the lang attribute on the <html> element."
    },
    {
      "requirement_id": "KDH-075",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Language of sections is verified by inspecting the HTML source for lang attributes on elements containing text in a different language."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışı, sistem çalıştırılarak ve girdi verilerek gözlenebilir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun tanımlı koşullarda otomatik sonlandırılması, sistem üzerinde süre ve koşul manipülasyonu yapılarak test edilebilir."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test"
      ],
      "rationale": "Denetim kayıtlarının gerekli alanları (tür, zaman, yer, kaynak, sonuç, kimlik) içerip içermediği, olaylar tetiklenerek ve loglar incelenerek doğrulanabilir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damgalarının UTC formatında ve iç sistem saatinden üretildiği, log kayıtları üzerinden gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme denemelerinin algılanması ve uyarı mekanizmasının çalışması, saldırı simülasyonları ile test edilebilir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Parola ve OTP giriş alanlarının maskeleme davranışı, kullanıcı arayüzünde girdi vererek gözlemlenebilir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolan oturumlarda yeniden kimlik doğrulama zorunluluğu, senaryo bazlı testlerle doğrulanabilir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test"
      ],
      "rationale": "Veri iletiminin şifreli ve bütünlüklü olduğu, ağ trafiği yakalama ve sertifika doğrulama testleri ile gözlenebilir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz, bozuk veya beklenmedik girdilerin sistemin reddetme ve hata yönetimi davranışları, negatif test vakaları ile doğrulanabilir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya gösterilen genel içeriği ile loglara yazılan ayrıntılı içeriğin farklılığı, hata senaryoları tetiklenerek gözlenebilir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum sonu uyarısı, taslak kaydetme ve yeniden doğrulama sonrası kaldığı yerden devam etme akışı, uçtan uca test ile doğrulanabilir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "Bot doğrulama eşiği aşımında etkileşimsiz kanıt isteme ve WCAG uyumlu nesne tanıma sorgusu gösterme davranışı, senaryo testleri ile gözlenebilir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "KÖA bildirimlerinin imza doğrulaması, belirsiz durum yönetimi ve sorgulama döngüsü, mock servisler kullanılarak test edilebilir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alanlı e-Devlet belirteçlerinde sınırlı kip açılması ve yönlendirme davranışı, farklı token senaryolarıyla test edilebilir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresi, bildirim zamanlaması ve ele geçirme kanıtında zorunlu değişiklik akışı, zaman manipülasyonu ve senaryo testleri ile doğrulanabilir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP adım penceresi (geçerli ve bir önceki adım) ve tek kullanımlık kod mantığı, zaman senkronizasyonu ve kod üretimi ile test edilebilir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiği aşımında doğrulayıcı devre dışı bırakma, hesap kurtarma ve sayaç sıfırlama akışı, tekrarlı başarısız giriş testleri ile doğrulanabilir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "Farklı AAL düzeylerinde hareketsizlik sonrası parola ile devam veya e-Devlet yönlendirme ve oturum sırrı silme davranışı, rol bazlı test senaryolarıyla gözlenebilir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırı aşımında en eski oturumun sonlandırılması, kullanıcı bildirimi ve SIEM loglama davranışı, çoklu oturum senaryolarıyla test edilebilir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, içerik imzası ve boyut/sayı sınırlarının denetlenmesi ile ret mesajlarının içeriği, farklı dosya yükleme testleri ile doğrulanabilir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement mandates the availability of specific authentication options, which is verified by executing the login process and observing the presented choices."
    },
    {
      "requirement_id": "KDH-002",
      "methods": [
        "Test"
      ],
      "rationale": "The system's ability to enforce multi-factor or two-factor authentication at AAL2 is verified by attempting logins with valid and invalid factor combinations."
    },
    {
      "requirement_id": "KDH-003",
      "methods": [
        "Test"
      ],
      "rationale": "Periodic reauthentication behavior based on inactivity and overall timeouts is verified by simulating user sessions with specific idle and active durations."
    },
    {
      "requirement_id": "KDH-004",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of notifications upon account recovery is verified by triggering a recovery event and observing the delivery of the notification."
    },
    {
      "requirement_id": "KDH-005",
      "methods": [
        "Test"
      ],
      "rationale": "The distribution of notifications to registered addresses (excluding postal) is verified by triggering a notification event and checking the recipients."
    },
    {
      "requirement_id": "KDH-006",
      "methods": [
        "Test"
      ],
      "rationale": "The independence of the VBP session from the e-Devlet assertion validity window is verified by maintaining a VBP session after the e-Devlet assertion expires."
    },
    {
      "requirement_id": "KDH-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The content of the assertion request, specifically the inclusion of the VBP identifier and cryptographic nonce, is verified by inspecting the network traffic or code implementation."
    },
    {
      "requirement_id": "KDH-008",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of the assertion audience is verified by attempting to inject an assertion generated for a different relying party and observing the rejection."
    },
    {
      "requirement_id": "KDH-009",
      "methods": [
        "Test"
      ],
      "rationale": "The enforcement of the binding process for changing the SMS telephone number is verified by attempting to change the number without completing the required binding authentication."
    },
    {
      "requirement_id": "KDH-010",
      "methods": [
        "Test"
      ],
      "rationale": "The ability to bind multiple authenticators is verified by adding more than one authenticator to a single account and confirming their coexistence."
    },
    {
      "requirement_id": "KDH-011",
      "methods": [
        "Test"
      ],
      "rationale": "The authentication level required for binding a new authenticator is verified by attempting to bind an authenticator at different AAL levels and observing the system's response."
    },
    {
      "requirement_id": "KDH-012",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of an independent notification upon adding an authenticator is verified by adding a new authenticator and checking for the notification via a separate channel."
    },
    {
      "requirement_id": "KDH-013",
      "methods": [
        "Test"
      ],
      "rationale": "The invalidation of a confirmation code after successful use is verified by using a code and then attempting to reuse it within its validity period."
    },
    {
      "requirement_id": "KDH-014",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of assertion signatures is verified by submitting an assertion with an invalid or tampered signature and observing the rejection."
    },
    {
      "requirement_id": "KDH-015",
      "methods": [
        "Test"
      ],
      "rationale": "Replay protection is verified by submitting the same valid e-Devlet assertion twice and observing the rejection of the second attempt."
    },
    {
      "requirement_id": "KDH-016",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The initiation of federation transactions by VBP as the RP is verified by inspecting the sequence of network requests or the code logic for the federation flow."
    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "The prevention of information leakage during proofing is verified by submitting mismatched self-asserted information and comparing the error messages with those for matched information."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of core attributes against authoritative sources or signed evidence is verified by submitting valid and invalid proofing data and observing the acceptance or rejection."
    },
    {
      "requirement_id": "KDH-019",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of a proofing notification to a validated address is verified by completing the IAL2 proofing process and checking for the notification at the specified address."
    },
    {
      "requirement_id": "KDH-020",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The prohibition of knowledge-based verification is verified by inspecting the code and configuration to ensure no such mechanism is implemented or enabled."
    },
    {
      "requirement_id": "KDH-021",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The prohibition of email for out-of-band authentication is verified by inspecting the authentication logic and configuration to ensure email is not used for this purpose."
    },
    {
      "requirement_id": "KDH-022",
      "methods": [
        "Test"
      ],
      "rationale": "The 5-minute validity window for SMS codes is verified by submitting a correct code after 5 minutes and observing the rejection, and before 5 minutes and observing the success."
    },
    {
      "requirement_id": "KDH-023",
      "methods": [
        "Test"
      ],
      "rationale": "The single-use nature of SMS codes is verified by submitting a valid code twice within its validity period and observing the rejection of the second attempt."
    },
    {
      "requirement_id": "KDH-024",
      "methods": [
        "Test"
      ],
      "rationale": "The non-resetting of the failed authentication count upon generating a new SMS code is verified by failing authentication, generating a new code, and checking the account's lockout status."
    },
    {
      "requirement_id": "KDH-025",
      "methods": [
        "Test"
      ],
      "rationale": "The absence of additional password composition requirements is verified by setting passwords that meet length and blocklist criteria but violate common composition rules (e.g., all lowercase) and observing their acceptance."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "ETC-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies behavioral triggers for establishing communication sessions, which must be verified by executing the system under various trigger conditions and observing the session establishment."
    },
    {
      "requirement_id": "ETC-002",
      "methods": [
        "Test"
      ],
      "rationale": "This negative requirement prevents duplicate session attempts, which is best verified by attempting to trigger a new session while one is active and observing that the system rejects the new attempt."
    },
    {
      "requirement_id": "ETC-003",
      "methods": [
        "Test"
      ],
      "rationale": "The behavior of terminating existing sessions to establish a new one, including specific exceptions for RBC transitions, requires dynamic testing of session management logic."
    },
    {
      "requirement_id": "ETC-004",
      "methods": [
        "Test"
      ],
      "rationale": "The sequential steps of session establishment, including retries and version compatibility checks, are dynamic behaviors that must be observed by running the system and monitoring message exchanges."
    },
    {
      "requirement_id": "ETC-005",
      "methods": [
        "Test"
      ],
      "rationale": "The selection logic for the radio system based on priority rules is a functional behavior that can be verified by configuring different inputs (trackside orders, driver choices) and observing which radio system is selected."
    },
    {
      "requirement_id": "ETC-006",
      "methods": [
        "Test"
      ],
      "rationale": "Verifying that the OBU memorizes the used radio system requires observing the internal state or subsequent behavior after a successful connection setup."
    },
    {
      "requirement_id": "ETC-007",
      "methods": [
        "Test"
      ],
      "rationale": "The abort conditions during session establishment are dynamic events that must be triggered and observed to ensure the session is correctly aborted and resources released."
    },
    {
      "requirement_id": "ETC-008",
      "methods": [
        "Test"
      ],
      "rationale": "The specific handling of the 'last known RBC' identity value requires testing with a trackside order containing this special value to verify the OBU uses stored contact information instead of the provided number."
    },
    {
      "requirement_id": "ETC-009",
      "methods": [
        "Test"
      ],
      "rationale": "This negative requirement is verified by sending a trackside order for the last known RBC when no contact info is stored and observing that the OBU ignores the order."
    },
    {
      "requirement_id": "ETC-010",
      "methods": [
        "Test"
      ],
      "rationale": "The immediate reconnection attempt using the previously successful radio system is a dynamic response to a connection loss event, best verified by simulating the loss and observing the reconnection behavior."
    },
    {
      "requirement_id": "ETC-011",
      "methods": [
        "Test"
      ],
      "rationale": "The persistent retry behavior until specific termination conditions are met requires observing the system's repeated attempts over time or until a stop condition is triggered."
    },
    {
      "requirement_id": "ETC-012",
      "methods": [
        "Test"
      ],
      "rationale": "Verifying that session termination is initiated only under specific conditions requires testing both valid termination triggers and invalid ones to ensure no unauthorized termination occurs."
    },
    {
      "requirement_id": "ETC-013",
      "methods": [
        "Test"
      ],
      "rationale": "The repetition of the Termination message upon lack of acknowledgement is a timing-dependent behavior that must be observed by monitoring message traffic and timing."
    },
    {
      "requirement_id": "ETC-014",
      "methods": [
        "Test"
      ],
      "rationale": "Determining the session as terminated after a defined number of retries and timeouts is a state transition that can be verified by observing the system state after the specified sequence of events."
    },
    {
      "requirement_id": "ETC-015",
      "methods": [
        "Test"
      ],
      "rationale": "The registration triggers (power-up, new network ID, trackside order) are dynamic events that must be executed to verify the OBU correctly initiates registration."
    },
    {
      "requirement_id": "ETC-016",
      "methods": [
        "Test"
      ],
      "rationale": "Using the default Radio Network type when no other information is available is a fallback behavior that can be verified by clearing stored data and observing the system's choice."
    },
    {
      "requirement_id": "ETC-017",
      "methods": [
        "Test"
      ],
      "rationale": "This negative requirement prevents connection setup under specific network registration conditions, which is verified by configuring the system to match these conditions and observing the lack of a connection request."
    },
    {
      "requirement_id": "ETC-018",
      "methods": [
