{
  "test_cases": [
    {
      "id": "TC-KDH-038-01",
      "title": "Disabling multiple authenticators after threshold exceeded",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with both a password and a second-factor authenticator (e.g., OTP) enabled. The failure threshold is defined in VBP SDD §14 (assumed to be 5 for this test).",
      "test_inputs": "Valid username, incorrect password, incorrect second-factor code.",
      "assumptions": "The threshold for consecutive failed attempts is 5. The system tracks failures per authenticator and per account.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt authentication with the correct username, an incorrect password, and an incorrect second-factor code.",
          "expected": "Authentication fails. The system records a failed attempt for both the password and the second-factor authenticator."
        },
        {
          "no": 2,
          "action": "Repeat the failed authentication attempt until the threshold (5th attempt) is reached.",
          "expected": "On the 5th failed attempt, the system disables both the password authenticator and the second-factor authenticator for the account."
        },
        {
          "no": 3,
          "action": "Attempt authentication again with the correct password and correct second-factor code.",
          "expected": "Authentication is denied because the authenticators are disabled. A message indicating that the authenticators are disabled or that account recovery is required is displayed."
        }
      ]
    },
    {
      "id": "TC-KDH-038-02",
      "title": "Authenticators remain active below threshold",
      "covers": [
        "KDH-038"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "A company representative account exists with both a password and a second-factor authenticator enabled. The failure threshold is defined in VBP SDD §14 (assumed to be 5).",
      "test_inputs": "Valid username, incorrect password, incorrect second-factor code.",
      "assumptions": "The threshold for consecutive failed attempts is 5.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt authentication with the correct username, an incorrect password, and an incorrect second-factor code 4 times consecutively.",
          "expected": "Each attempt fails. The authenticators remain enabled and active."
        },
        {
          "no": 2,
          "action": "Attempt authentication with the correct password and correct second-factor code.",
          "expected": "Authentication succeeds. The user is logged in."
        }
      ]
    },
    {
      "id": "TC-KDH-038-03",
      "title": "Disabling authenticators when only one factor is used in failures",
      "covers": [
        "KDH-038"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "A company representative account exists with both a password and a second-factor authenticator enabled. The failure threshold is defined in VBP SDD §14 (assumed to be 5).",
      "test_inputs": "Valid username, incorrect password, correct second-factor code.",
      "assumptions": "The system tracks failures per authenticator. The requirement states 'if more than one authenticator is involved... VBP shall disable all of the authenticators involved'. This test checks if the system correctly identifies which authenticators are involved in the failures. If only the password is wrong, only the password is 'involved' in the failure logic, but the requirement says 'if more than one authenticator is involved... disable all'. This is ambiguous. However, typically 'involved' means the ones that failed. Let's assume the requirement implies that if the *account* reaches the threshold via multiple factors, all are disabled. If only one factor fails, only that one might be disabled, or the account is locked. Given the specific wording 'if more than one authenticator is involved... disable all', this test case explores the scenario where only one factor is consistently wrong. If the system disables *all* authenticators even if only one failed, it might be overly restrictive. If it disables only the failed one, it complies with 'disable all of the authenticators involved' (where involved = failed). Let's test the behavior when only the password fails.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt authentication with the correct username, an incorrect password, and a correct second-factor code 5 times consecutively.",
          "expected": "Authentication fails 5 times. The system disables the password authenticator. The second-factor authenticator remains enabled (as it was not involved in the failure)."
        },
        {
          "no": 2,
          "action": "Attempt authentication with the correct password and correct second-factor code.",
          "expected": "Authentication is denied because the password authenticator is disabled."
        }
      ]
    }
  ]
}

